// Meetup member record page (moderators): profile + event history (RSVPs / attendance).
import React, { useEffect, useState } from 'react';
import { Linking, View } from 'react-native';
import { router, Stack, useLocalSearchParams } from 'expo-router';
import { Avatar, Button, EmptyState, ErrorText, HighlightPanel, ListRow, ListView, Page, StatusPill, type Column } from '../../../components/ui';
import { NotFound, useCanModerate } from '../../../components/mod';
import { RsvpPill } from '../../../components/attendance';
import { getMeetupMember, listRsvpsForMember, openDm, type MeetupMember } from '../../../lib/api';
import { fmtDate } from '../../../lib/format';

const COLS: Column[] = [{ label: 'Event', flex: 2 }, { label: 'Date', width: 110 }, { label: 'Status', width: 110 }];

export default function MeetupMemberPage() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const mid = decodeURIComponent(id ?? '');
  const { ready, ok, userId } = useCanModerate();
  const [m, setM] = useState<MeetupMember | null | undefined>(undefined);
  const [hist, setHist] = useState<Awaited<ReturnType<typeof listRsvpsForMember>> | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [opening, setOpening] = useState(false);
  useEffect(() => {
    if (!ok || !mid) return;
    getMeetupMember(mid).then(setM).catch((x) => setErr(x.message));
    listRsvpsForMember(mid).then(setHist).catch((x) => setErr(x.message));
  }, [ok, mid]);
  const message = async () => {
    if (!m?.profile_id) return;
    setOpening(true); setErr(null);
    try { router.push(`/rooms/${await openDm(m.profile_id)}`); }
    catch (e: any) { setErr(e.message); }
    finally { setOpening(false); }
  };

  if (!ready) return <View style={{ flex: 1 }} />;
  if (!ok) return <NotFound />;
  return (
    <Page>
      <Stack.Screen options={{ title: m?.name ?? 'Member' }} />
      <ErrorText>{err}</ErrorText>
      {m === null ? <EmptyState title="Member not found" body="They may have left the group. Try syncing Meetup members from Chat." /> : null}
      {m ? <HighlightPanel media={<Avatar name={m.name ?? '?'} uri={m.photo_url} size={56} />} eyebrow="Meetup member" title={m.name ?? '(no name)'}
        subtitle={m.city ?? undefined}
        pills={<>
          {m.role && m.role !== 'MEMBER' ? <StatusPill label={m.role.toLowerCase().replace(/_/g, ' ')} tone="info" /> : null}
          {m.profile_id ? <StatusPill label={`On the app${m.profile_name ? ` as ${m.profile_name}` : ''}`} tone="success" /> : null}
        </>}
        actions={<>
          {m.profile_id && m.profile_id !== userId ? <Button small icon="chatbubble-outline" title="Message" loading={opening} onPress={message} /> : null}
          {m.profile_url ? <Button small variant="neutral" icon="open-outline" title="Open on Meetup" onPress={() => Linking.openURL(m.profile_url!)} /> : null}
        </>}
        fields={[['Joined', fmtDate(m.joined_at)], ['Last visit', fmtDate(m.last_visited_at)], ['RSVPs (yes)', m.rsvp_yes], ['Attended', m.attended]]} /> : null}
      <ListView title="Event history" count={hist ? hist.length : undefined} columns={COLS} loading={!hist && !err}
        empty={<EmptyState icon="calendar-outline" title="No RSVPs synced" body="RSVPs appear after a Members sync." />}>
        {(hist ?? []).map((r) => (
          <ListRow key={r.meetup_event_id} columns={COLS} onPress={() => router.push(`/meetup/${encodeURIComponent(r.meetup_event_id)}`)}
            dim={r.response !== 'YES'}
            cells={[r.event?.title ?? r.meetup_event_id, r.event?.starts_at ? new Date(r.event.starts_at).toLocaleDateString() : '—', <RsvpPill r={r} />]} />
        ))}
      </ListView>
    </Page>
  );
}
